function App() {
  const nombre = 'Estudiante';
  const cursos = ['HTML', 'CSS', 'JavaScript', 'React'];

  return (
    <div style={{ padding: '24px', fontFamily: 'sans-serif' }}>
      <h1>Hola, {nombre} 👋</h1>
      <p>Tus cursos:</p>
      <ul>
        {cursos.map((curso) => (
          <li key={curso}>{curso}</li>
        ))}
      </ul>
    </div>
  );
}

function Badge({ texto, color }) {
  return (
    <span style={{
      background: color,
      color: 'white',
      padding: '4px 12px',
      borderRadius: '9999px',
      fontSize: '0.875rem',
      fontWeight: 600,
    }}>
      {texto}
    </span>
  );
}

function App() {
  return (
    <div style={{ padding: '24px', display: 'flex', gap: '8px' }}>
      <Badge texto="React" color="#61DAFB" />
      <Badge texto="CSS" color="#264DE4" />
      <Badge texto="HTML" color="#E44D26" />
    </div>
  );
}

